import os
import json
import time
import hmac
import hashlib
import secrets
import threading
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import parse_qs, urlparse

SESSION_DIR = os.path.join(os.environ.get('SESSION_DIR', '/var/lib/app/sessions'))
SECRET = os.environ.get('APP_SECRET', secrets.token_hex(32))

# PBKDF2 parameters for password hashing
PBKDF2_ITERATIONS = 200000
PBKDF2_DGST = 'sha256'

def constant_time_compare(a, b):
    return hmac.compare_digest(a.encode() if isinstance(a, str) else a,
                               b.encode() if isinstance(b, str) else b)

def hash_password(password, salt):
    """Derive a salted, key-stretched hash of the password."""
    if isinstance(salt, str):
        salt = bytes.fromhex(salt)
    dk = hashlib.pbkdf2_hmac(PBKDF2_DGST, password.encode(), salt, PBKDF2_ITERATIONS)
    return dk.hex()

def sign_token(session_id):
    sig = hmac.new(SECRET.encode(), session_id.encode(), hashlib.sha256).hexdigest()
    return f"{session_id}.{sig}"

def verify_token(token):
    if '.' not in token:
        return None
    session_id, sig = token.rsplit('.', 1)
    expected = hmac.new(SECRET.encode(), session_id.encode(), hashlib.sha256).hexdigest()
    if constant_time_compare(sig, expected):
        return session_id
    return None

def read_session_file(session_id):
    """Read session data from disk. Returns dict or None."""
    if not session_id or not session_id.isalnum():
        return None
    path = os.path.join(SESSION_DIR, f"{session_id}.json")
    # Ensure we're reading from the correct directory
    real_path = os.path.realpath(path)
    if not real_path.startswith(os.path.realpath(SESSION_DIR) + os.sep):
        return None
    try:
        with open(real_path, 'r') as f:
            data = json.load(f)
        return data
    except (IOError, json.JSONDecodeError, OSError):
        return None

def write_session_file(session_id, data):
    """Write session data to disk atomically."""
    if not session_id or not session_id.isalnum():
        return False
    path = os.path.join(SESSION_DIR, f"{session_id}.json")
    real_path = os.path.realpath(path)
    if not real_path.startswith(os.path.realpath(SESSION_DIR) + os.sep):
        return False
    tmp_path = real_path + f".tmp.{os.getpid()}"
    try:
        with open(tmp_path, 'w') as f:
            json.dump(data, f)
        os.replace(tmp_path, real_path)
        return True
    except OSError:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        return False

def create_session(user_id, role):
    """Create a new session for the given user."""
    session_id = secrets.token_hex(16)
    session_data = {
        'user_id': user_id,
        'role': role,
        'created_at': time.time(),
        'expires_at': time.time() + 3600,
        'last_activity': time.time()
    }
    if write_session_file(session_id, session_data):
        return sign_token(session_id)
    return None

def validate_and_get_session(token):
    """Validate token signature, check expiry, return session.

    Security model:
    1. Verify HMAC signature on token
    2. Read session data (single atomic read)
    3. Check expiration
    4. Update last_activity in background (non-blocking)
    5. Return the ORIGINAL validated session data for authorization
    """
    session_id = verify_token(token)
    if session_id is None:
        return None

    # Single read - use THIS data for all authorization decisions
    session_data = read_session_file(session_id)
    if session_data is None:
        return None

    if time.time() > session_data.get('expires_at', 0):
        # Session expired, clean up
        try:
            path = os.path.join(SESSION_DIR, f"{session_id}.json")
            os.unlink(os.path.realpath(path))
        except OSError:
            pass
        return None

    # Update activity timestamp in background - does NOT affect
    # the session_data we already read and will return
    def _update_activity():
        current = read_session_file(session_id)
        if current:
            current['last_activity'] = time.time()
            write_session_file(session_id, current)

    t = threading.Thread(target=_update_activity, daemon=True)
    t.start()

    # Return the data we validated - not a re-read
    return session_data


class AppHandler(BaseHTTPRequestHandler):

    def log_message(self, format, *args):
        pass  # Suppress default logging

    def get_token(self):
        cookie_header = self.headers.get('Cookie', '')
        for part in cookie_header.split(';'):
            part = part.strip()
            if part.startswith('session='):
                return part[8:]
        return None

    def send_json(self, code, data):
        body = json.dumps(data).encode()
        self.send_response(code)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        parsed = urlparse(self.path)

        if parsed.path == '/api/profile':
            self.handle_profile()
        elif parsed.path == '/api/admin/users':
            self.handle_admin_users()
        elif parsed.path == '/api/admin/config':
            self.handle_admin_config()
        else:
            self.send_json(404, {'error': 'not found'})

    def do_POST(self):
        parsed = urlparse(self.path)

        if parsed.path == '/api/login':
            self.handle_login()
        elif parsed.path == '/api/logout':
            self.handle_logout()
        else:
            self.send_json(404, {'error': 'not found'})

    def require_auth(self, required_role=None):
        """Authenticate request and optionally check role.
        Returns session data or None (sends error response if auth fails)."""
        token = self.get_token()
        if not token:
            self.send_json(401, {'error': 'authentication required'})
            return None

        session = validate_and_get_session(token)
        if session is None:
            self.send_json(401, {'error': 'invalid or expired session'})
            return None

        if required_role and session.get('role') != required_role:
            self.send_json(403, {'error': 'insufficient privileges'})
            return None

        return session

    def handle_profile(self):
        session = self.require_auth()
        if session is None:
            return
        self.send_json(200, {
            'user_id': session.get('user_id'),
            'role': session.get('role'),
            'last_activity': session.get('last_activity')
        })

    def handle_admin_users(self):
        session = self.require_auth(required_role='admin')
        if session is None:
            return
        # Admin-only: list all sessions
        users = []
        try:
            for fname in os.listdir(SESSION_DIR):
                if fname.endswith('.json') and not '.tmp.' in fname:
                    fpath = os.path.join(SESSION_DIR, fname)
                    try:
                        with open(fpath, 'r') as f:
                            sdata = json.load(f)
                        users.append({'user_id': sdata.get('user_id'), 'role': sdata.get('role')})
                    except (IOError, json.JSONDecodeError):
                        pass
        except OSError:
            pass
        self.send_json(200, {'users': users})

    def handle_admin_config(self):
        session = self.require_auth(required_role='admin')
        if session is None:
            return
        self.send_json(200, {'config': {'max_sessions': 1000, 'timeout': 3600}})

    def handle_login(self):
        content_length = int(self.headers.get('Content-Length', 0))
        if content_length > 4096:
            self.send_json(400, {'error': 'request too large'})
            return
        body = self.rfile.read(content_length)
        try:
            creds = json.loads(body)
        except json.JSONDecodeError:
            self.send_json(400, {'error': 'invalid json'})
            return

        username = creds.get('username', '')
        password = creds.get('password', '')

        if not isinstance(username, str) or not isinstance(password, str):
            self.send_json(400, {'error': 'invalid credentials format'})
            return

        # Simulated user database (in production, use proper DB).
        # Passwords stored as salted, key-stretched PBKDF2-HMAC-SHA256 hashes.
        users_db = {
            'admin': {
                'salt': '0f1e2d3c4b5a69788796a5b4c3d2e1f0',
                'password_hash': hash_password('admin_secret_pw_2024!', '0f1e2d3c4b5a69788796a5b4c3d2e1f0'),
                'role': 'admin'
            },
            'user1': {
                'salt': '112233445566778899aabbccddeeff00',
                'password_hash': hash_password('user1_password!', '112233445566778899aabbccddeeff00'),
                'role': 'user'
            },
            'user2': {
                'salt': 'ffeeddccbbaa99887766554433221100',
                'password_hash': hash_password('user2_password!', 'ffeeddccbbaa99887766554433221100'),
                'role': 'user'
            },
        }

        user = users_db.get(username)
        if user is None:
            # Perform equivalent work to avoid user enumeration via timing
            hash_password(password, secrets.token_hex(16))
            self.send_json(401, {'error': 'invalid credentials'})
            return

        if not constant_time_compare(
            hash_password(password, user['salt']),
            user['password_hash']
        ):
            self.send_json(401, {'error': 'invalid credentials'})
            return

        token = create_session(username, user['role'])
        if token is None:
            self.send_json(500, {'error': 'session creation failed'})
            return

        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Set-Cookie', f'session={token}; HttpOnly; SameSite=Strict; Path=/')
        body = json.dumps({'message': 'login successful'}).encode()
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def handle_logout(self):
        token = self.get_token()
        if token:
            session_id = verify_token(token)
            if session_id and session_id.isalnum():
                try:
                    path = os.path.join(SESSION_DIR, f"{session_id}.json")
                    real_path = os.path.realpath(path)
                    if real_path.startswith(os.path.realpath(SESSION_DIR) + os.sep):
                        os.unlink(real_path)
                except OSError:
                    pass
        self.send_json(200, {'message': 'logged out'})


if __name__ == '__main__':
    os.makedirs(SESSION_DIR, mode=0o700, exist_ok=True)
    server = HTTPServer(('127.0.0.1', 8080), AppHandler)
    server.serve_forever()
